<?php require APP_PATH.'Views/layouts/header.php';require APP_PATH.'Views/layouts/sidebar.php';$csrf=generate_csrf_token();$tone=fn($s)=>$s==='Valid'?'success':($s==='Expiring Soon'?'warning':(in_array($s,['Expired','Revoked'],true)?'danger':'primary')); ?>
<div id="main-content"><?php require APP_PATH.'Views/layouts/navbar.php'; ?>
 <div class="module-toolbar my-3"><div class="module-toolbar-title"><span class="module-toolbar-icon"><i class="fa-solid fa-certificate"></i></span><div><h5><?= $is_admin?'Employee Certification Registry':'My Certifications'; ?></h5><small>Credential verification, validity and expiration monitoring</small></div></div><?php if($is_admin): ?><button class="btn btn-primary btn-sm" data-bs-toggle="modal" data-bs-target="#certModal"><i class="fa-solid fa-plus"></i>Add Certification</button><?php endif; ?></div>
 <div class="glass-card p-4"><div class="alert alert-light border"><i class="fa-solid fa-bell text-primary me-2"></i>Certifications are flagged <strong><?= (int)$warning_days; ?> days</strong> before expiration. Training completion certificates remain linked to their original training record.</div>
 <form class="row g-2 align-items-end mb-3" method="get"><input type="hidden" name="page" value="certifications"><div class="col-md-6"><label class="form-label">Internal Certificate Verification Code</label><input class="form-control" name="verification_code" maxlength="64" value="<?= htmlspecialchars($verification_code??''); ?>" placeholder="Enter code printed on the PDF"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Verify</button></div></form><?php if(!empty($verification_code)): ?><div class="alert <?= $verification_result?'alert-success':'alert-danger'; ?>"><?php if($verification_result): ?><strong>VALID:</strong> <?= htmlspecialchars($verification_result['certificate_number']); ?> — <?= htmlspecialchars($verification_result['employee_name']); ?>, <?= htmlspecialchars($verification_result['training_title']??$verification_result['certification_name']); ?> (<?= htmlspecialchars($verification_result['status']); ?>)<?php else: ?><strong>Not found.</strong> The code is invalid or is not authorized for your employee account.<?php endif; ?></div><?php endif; ?>
 <?php $numbered=array_values(array_filter($certifications,fn($item)=>!empty($item['certificate_number'])));if($numbered): ?><div class="row g-2 mb-3"><?php foreach($numbered as $item): ?><div class="col-lg-4 col-md-6"><div class="border rounded p-3 h-100"><small class="text-secondary"><?= htmlspecialchars($item['certification_name']); ?></small><strong class="d-block"><?= htmlspecialchars($item['certificate_number']); ?> <span class="badge badge-soft-info">v<?= (int)$item['certificate_version']; ?></span></strong><small class="text-secondary">Issued <?= $item['issue_date']?date('M j, Y',strtotime($item['issue_date'])):'—'; ?></small><?php if($is_admin&&$item['related_training_registration_id']): ?><button class="btn btn-outline-primary btn-sm d-block mt-2 cert-regenerate" data-id="<?= (int)$item['related_training_registration_id']; ?>">Regenerate PDF</button><?php endif; ?></div></div><?php endforeach; ?></div><?php endif; ?>
 <?php if($is_admin): ?><div class="row g-2 mb-3"><div class="col-md-4"><select id="certEmployeeFilter" class="form-select"><option value="">All employees</option><?php foreach($employees as $e): ?><option><?= htmlspecialchars($e['first_name'].' '.$e['last_name']); ?></option><?php endforeach; ?></select></div><div class="col-md-4"><select id="certTypeFilter" class="form-select"><option value="">All certification types</option><?php foreach(array_unique(array_column($certifications,'certification_type')) as $type): ?><option><?= htmlspecialchars($type); ?></option><?php endforeach; ?></select></div><div class="col-md-4"><select id="certStatusFilter" class="form-select"><option value="">All statuses</option><?php foreach(EmployeeCertification::STATUSES as $status): ?><option><?= $status; ?></option><?php endforeach; ?></select></div></div><?php endif; ?>
 <div class="table-responsive"><table id="certificationTable" class="table align-middle datatable-init"><thead><tr><?php if($is_admin): ?><th>Employee</th><?php endif; ?><th>Certification</th><th>Type</th><th>Issuer</th><th>Validity</th><th>Status</th><th>Related Training</th><th>Verification</th><th>Actions</th></tr></thead><tbody><?php foreach($certifications as $c): ?><tr><?php if($is_admin): ?><td><strong><?= htmlspecialchars($c['employee_name']); ?></strong><small class="d-block text-secondary"><?= htmlspecialchars($c['employee_code']); ?></small></td><?php endif; ?><td><strong><?= htmlspecialchars($c['certification_name']); ?></strong></td><td><?= htmlspecialchars($c['certification_type']); ?></td><td><?= htmlspecialchars($c['issuing_organization']??'—'); ?></td><td><?= $c['issue_date']?date('M j, Y',strtotime($c['issue_date'])):'—'; ?><small class="d-block <?= $c['days_remaining']!==null&&(int)$c['days_remaining']<=(int)$warning_days?'text-danger fw-bold':'text-secondary'; ?>"><?= $c['expiration_date']?'Expires '.date('M j, Y',strtotime($c['expiration_date'])).' ('.((int)$c['days_remaining']>=0?(int)$c['days_remaining'].' days left':abs((int)$c['days_remaining']).' days overdue').')':'No expiration'; ?></small></td><td><span class="badge badge-soft-<?= $tone($c['status']); ?>"><?= htmlspecialchars($c['status']); ?></span></td><td><?= htmlspecialchars($c['training_title']??'External / Not linked'); ?></td><td><?= $c['verification_date']?htmlspecialchars($c['verifier_name']).'<small class="d-block text-secondary">'.date('M j, Y',strtotime($c['verification_date'])).'</small>':'Pending'; ?></td><td><div class="table-action-group"><?php if($c['supporting_file']): ?><a class="btn btn-outline-primary btn-sm" href="index.php?page=certifications_download&amp;id=<?= (int)$c['id']; ?>">File</a><?php endif; ?><?php if($is_admin): ?><button class="btn btn-outline-primary btn-sm cert-edit" data-record='<?= htmlspecialchars(json_encode($c),ENT_QUOTES,'UTF-8'); ?>' data-bs-toggle="modal" data-bs-target="#certModal">Edit</button><?php if($c['status']==='Pending Verification'): ?><button class="btn btn-outline-success btn-sm cert-verify" data-id="<?= (int)$c['id']; ?>" data-status="Valid">Verify</button><?php endif; ?><?php if($c['status']!=='Revoked'): ?><button class="btn btn-outline-danger btn-sm cert-verify" data-id="<?= (int)$c['id']; ?>" data-status="Revoked">Revoke</button><?php endif; ?><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></div>
</div>
<?php if($is_admin): ?><div class="modal fade" id="certModal"><div class="modal-dialog modal-lg modal-dialog-centered"><form class="modal-content" id="certForm" enctype="multipart/form-data"><div class="modal-header"><h5 class="modal-title">Certification Record</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><input type="hidden" name="csrf_token" value="<?= $csrf; ?>"><input type="hidden" name="id" id="certId"><div class="col-md-6"><label class="form-label">Employee *</label><select class="form-select" name="employee_id" id="certEmployee" required><option value="">Select employee</option><?php foreach($employees as $e): ?><option value="<?= (int)$e['id']; ?>"><?= htmlspecialchars($e['employee_code'].' - '.$e['first_name'].' '.$e['last_name']); ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Certification Name *</label><input class="form-control" name="certification_name" id="certName" maxlength="180" required></div><div class="col-md-4"><label class="form-label">Type *</label><input class="form-control" name="certification_type" id="certType" maxlength="100" placeholder="Professional, Compliance, License..." required></div><div class="col-md-4"><label class="form-label">Issuing Organization</label><input class="form-control" name="issuing_organization" id="certIssuer" maxlength="180"></div><div class="col-md-4"><label class="form-label">Status *</label><select class="form-select" name="status" id="certStatus"><?php foreach(EmployeeCertification::STATUSES as $status): ?><option><?= $status; ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Issue Date</label><input type="date" class="form-control" name="issue_date" id="certIssue"></div><div class="col-md-4"><label class="form-label">Expiration Date</label><input type="date" class="form-control" name="expiration_date" id="certExpiry"></div><div class="col-md-4"><label class="form-label">Related Training</label><select class="form-select" name="related_training_id" id="certTraining"><option value="">External / None</option><?php foreach($trainings as $t): ?><option value="<?= (int)$t['id']; ?>"><?= htmlspecialchars($t['title']); ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Supporting File</label><input type="file" class="form-control" name="supporting_file" accept=".pdf,.jpg,.jpeg,.png"><small class="form-text">PDF or image, maximum 5 MB. Existing training certificate files are reused, not copied.</small></div></div><div class="modal-footer"><button class="btn btn-primary">Save Certification</button></div></form></div></div><?php endif; ?>
<script>$(function(){const csrf=<?= json_encode($csrf); ?>,send=(url,data)=>$.post(url,data,null,'json').done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),600)}else showErrorDialog(r.message)}).fail(x=>showErrorDialog(x.responseJSON?.message||'Request failed.'));<?php if($is_admin): ?>setTimeout(()=>{if(!$.fn.DataTable.isDataTable('#certificationTable'))return;const t=$('#certificationTable').DataTable();$('#certEmployeeFilter').change(function(){t.column(0).search(this.value).draw()});$('#certTypeFilter').change(function(){t.column(2).search(this.value).draw()});$('#certStatusFilter').change(function(){t.column(5).search(this.value).draw()})},0);$('#certModal').on('hidden.bs.modal',function(){$('#certForm')[0].reset();$('#certId').val('')});$('.cert-edit').click(function(){const c=$(this).data('record');$('#certId').val(c.id);$('#certEmployee').val(c.employee_id);$('#certName').val(c.certification_name);$('#certType').val(c.certification_type);$('#certIssuer').val(c.issuing_organization);$('#certStatus').val(c.status);$('#certIssue').val(c.issue_date);$('#certExpiry').val(c.expiration_date);$('#certTraining').val(c.related_training_id||'')});$('#certForm').submit(function(e){e.preventDefault();$.ajax({url:'index.php?page=certifications_save',type:'POST',data:new FormData(this),contentType:false,processData:false,dataType:'json'}).done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),600)}else showErrorDialog(r.message)}).fail(x=>showErrorDialog(x.responseJSON?.message||'Request failed.'))});$('.cert-verify').click(function(){send('index.php?page=certifications_verify',{id:this.dataset.id,status:this.dataset.status,csrf_token:csrf})});<?php endif; ?>});</script>
<?php if($is_admin): ?><script>$(function(){$('.cert-regenerate').click(function(){const id=this.dataset.id;Swal.fire({title:'Regenerate Certificate',input:'text',inputLabel:'Reason for regeneration',inputPlaceholder:'Formatting correction or signatory update',showCancelButton:true,confirmButtonText:'Regenerate',inputValidator:v=>!v?'A reason is required.':undefined}).then(x=>{if(!x.isConfirmed)return;$.post('index.php?page=training_certificate_regenerate',{registration_id:id,reason:x.value,csrf_token:<?= json_encode($csrf); ?>},null,'json').done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),600)}else showErrorDialog(r.message)}).fail(x=>showErrorDialog(x.responseJSON?.message||'Regeneration failed.'))})})});</script><?php endif; ?>
